export function resolveCollision(ball, brick) {
  const overlapX = Math.min(ball.x + ball.r - brick.x, brick.x + brick.w - (ball.x - ball.r));
  const overlapY = Math.min(ball.y + ball.r - brick.y, brick.y + brick.h - (ball.y - ball.r));

  if (overlapX < overlapY) {
    // Side hit
    ball.vx = -Math.sign(ball.vx) * Math.abs(ball.vx); // Ensure flip
    // To avoid sticking, we can't just flip, we must reposition.
    // However, the simplest is to just flip and let the next frame handle it.
    // But D2 requires pushing it out.
    if (ball.x < brick.x + brick.w / 2) {
      ball.x = brick.x - ball.r;
    } else {
      ball.x = brick.x + brick.w + ball.r;
    }
  } else {
    // Top/Bottom hit
    ball.vy = -Math.sign(ball.vy) * Math.abs(ball.vy);
    if (ball.y < brick.y + brick.h / 2) {
      ball.y = brick.y - ball.r;
    } else {
      ball.y = brick.y + brick.h + ball.r;
    }
  }
}

