import { test } from 'node:test';
import assert from 'node:assert';
import { createState, collides, frame } from '../game/neon.js';

const mockCtx = {
  fillStyle: '',
  fillRect: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
  fillText: () => {},
};

test('D1 - No bounce: ball should change direction upon collision', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - state.ball.r + 1;

  frame(mockCtx, state);

  console.log('Ball vy after frame:', state.ball.vy);
  assert.strictEqual(state.ball.vy < 0, true, 'Ball should have bounced UP (vy < 0)');
});

test('D2 - Sticky: ball should not get stuck inside brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y + 2; // Already inside
  state.ball.vy = 100;

  frame(mockCtx, state);
  assert.strictEqual(collides(state.ball, brick), false, 'Ball should be pushed out of the brick');
});

test('D3 - Corner: ball should bounce on both axes when hitting corner', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x - state.ball.r + 1;
  state.ball.y = brick.y - state.ball.r + 1;
  state.ball.vx = 100;
  state.ball.vy = 100;

  frame(mockCtx, state);

  assert.strictEqual(state.ball.vx < 0, true, 'vx should have flipped');
  assert.strictEqual(state.ball.vy < 0, true, 'vy should have flipped');
});

test('D4 - Tunneling: ball should not pass through brick at high speed', () => {
  const state = createState(6);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - state.ball.r - 1;
  state.ball.vy = 1000;

  state.ball.y += state.ball.vy * 0.05;
  frame(mockCtx, state);

  assert.ok(state.ball.y < brick.y + brick.h, 'Ball tunneled through the brick');
});

